const items = $input.all();

return items.map((item) => {
  const data = item.json;

  const contentId = data.contentId ?? "";
  const title = String(data.title ?? "").trim();
  const description = String(data.description ?? "").trim();
  const platform = String(data.platform ?? "").trim().toLowerCase();

  const aiPrompt = `
Bạn là AI phân tích nội dung đối thủ trên mạng xã hội.

Hãy phân tích nội dung video dựa CHỈ trên title và description được cung cấp.
Không tự bịa thêm thông tin không có trong dữ liệu.

THÔNG TIN VIDEO:
- Platform: ${platform}
- Content ID: ${contentId}
- Title: ${title}
- Description:
${description}

Hãy trả về DUY NHẤT một JSON object hợp lệ, không markdown, không \`\`\`json.

JSON bắt buộc có đúng các field sau:

{
  "topic": "Chủ đề chính của nội dung",
  "category": "Nhóm/chủ đề lớn",
  "content_type": "Loại nội dung",
  "sentiment": "Tích cực | Trung tính | Tiêu cực",
  "keywords": ["từ khóa 1", "từ khóa 2", "từ khóa 3"],
  "summary": "Tóm tắt ngắn gọn nội dung",
  "target_audience": "Đối tượng khán giả mục tiêu",
  "key_message": "Thông điệp chính của nội dung"
}

QUY TẮC:
1. topic phải mô tả chủ đề chính.
2. category phải là nhóm lớn bằng TIẾNG VIỆT, ví dụ: Công nghệ, Khoa học, Giáo dục, Giải trí, Kinh doanh, Xã hội.
3. content_type là các dạng nội dung bằng TIẾNG VIỆT như: Phỏng vấn, Hướng dẫn, Đánh giá, Giải thích, Phim tài liệu, Tin tức, Thử nghiệm, Thuyết trình.
4. sentiment chỉ được là 1 trong 3 giá trị: Tích cực, Trung tính hoặc Tiêu cực.
5. keywords phải là một mảng string bằng tiếng Việt.
6. summary phải ngắn gọn nhưng phản ánh đúng nội dung.
7. target_audience phải dựa trên nội dung thực tế được cung cấp.
8. key_message phải nêu được thông điệp chính.
9. Không được thêm field ngoài 8 field đã yêu cầu.
10. JSON phải hợp lệ để hệ thống có thể parse tự động.
11. TẤT CẢ GIÁ TRỊ TRONG JSON BẮT BUỘC TRẢ VỀ BẰNG TIẾNG VIỆT.
`.trim();

  return {
    json: {
      id: data.id ?? null,
      competitor_id: data.competitorId ?? null,
      platform,
      content_id: contentId,
      title,
      description,
      url: data.url ?? null,
      published_at: data.publishedAt ?? null,
      created_at: data.createdAt ?? null,

      ai_prompt: aiPrompt
    }
  };
});

const aiItems = $input.all();
const originalItems = $('04 - Prepare AI Input').all();

if (aiItems.length !== originalItems.length) {
  throw new Error(
    `Số lượng item không khớp: AI=${aiItems.length}, Original=${originalItems.length}`
  );
}

function parseAIResult(value) {
  if (value && typeof value === 'object') {
    return value;
  }
  if (typeof value === 'string') {
    let text = value.trim();
    text = text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();
    try {
      return JSON.parse(text);
    } catch (error) {
      throw new Error(
        `AI trả về JSON không hợp lệ: ${text.substring(0, 300)}`
      );
    }
  }
  throw new Error('Không tìm thấy nội dung AI để parse');
}

const output = [];

for (let i = 0; i < aiItems.length; i++) {
  const ai = aiItems[i].json;
  const original = originalItems[i].json;

  // Lấy dữ liệu theo CẤU TRÚC MỚI NHẤT CỦA GEMINI (Không vòng lặp)
  // Đường dẫn: content -> parts -> [0] -> text
  const geminiText = ai.content?.parts?.[0]?.text;

  // Dự phòng cho cấu trúc OpenAI cũ (nếu sau này đổi lại)
  const openAiText = ai.output?.[0]?.content?.[0]?.text;

  // Dự phòng cho cấu trúc Basic LLM Chain cũ
  const basicLLMText = ai.text;

  // Ưu tiên lấy rawText theo thứ tự cấu trúc mới nhất
  const rawText = geminiText || openAiText || basicLLMText;

  if (!rawText) {
    throw new Error(
      `Không tìm thấy AI content tại index ${i}`
    );
  }

  const analysis = parseAIResult(rawText);

  output.push({
    json: {
      id: original.id ?? null,
      competitor_id: original.competitor_id ?? null,
      platform: original.platform ?? null,
      content_id: original.content_id ?? null,
      title: original.title ?? "",
      description: original.description ?? "",
      url: original.url ?? null,
      published_at: original.published_at ?? null,

      topic: analysis.topic ?? null,
      category: analysis.category ?? null,
      content_type: analysis.content_type ?? null,
      sentiment: analysis.sentiment ?? null,
      keywords: Array.isArray(analysis.keywords)
        ? analysis.keywords
        : [],
      summary: analysis.summary ?? null,
      target_audience: analysis.target_audience ?? null,
      key_message: analysis.key_message ?? null
    }
  });
}

return output;

const items = $input.all();

const requiredFields = [
  'content_id',
  'topic',
  'category',
  'content_type',
  'sentiment',
  'keywords',
  'summary',
  'target_audience',
  'key_message'
];

// Đã cập nhật giá trị tiếng Việt. Bổ sung thêm các biến thể viết thường và tiếng Anh để dự phòng AI trả về không đồng nhất
const validSentiments = [
  'Tích cực', 'Trung tính', 'Tiêu cực',
  'tích cực', 'trung tính', 'tiêu cực',
  'positive', 'neutral', 'negative'
];

return items.map((item) => {
  const data = item.json;
  const errors = [];

  for (const field of requiredFields) {
    if (
      data[field] === null ||
      data[field] === undefined ||
      data[field] === ''
    ) {
      errors.push(`${field} bị thiếu`);
    }
  }

  if (
    data.keywords !== null &&
    data.keywords !== undefined &&
    !Array.isArray(data.keywords)
  ) {
    errors.push('keywords phải là array');
  }

  if (
    data.sentiment &&
    !validSentiments.includes(data.sentiment)
  ) {
    errors.push(
      `sentiment không hợp lệ: ${data.sentiment}`
    );
  }

  return {
    json: {
      ...data,
      is_valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      content_id: data.content_id ?? null,
      title: data.title ?? "",
      platform: data.platform ?? null,

      processing_status: "ai_invalid",

      validation_errors: Array.isArray(data.validation_errors)
        ? data.validation_errors
        : ["AI output không hợp lệ"]
    }
  };
});
